'use strict';
const test=require('node:test');const assert=require('node:assert/strict');
const {normalizeV2Page,createV2PageFetcher,loadV2}=require('./proxy-contract');
const station=(id)=>({id,geom:{lat:43.3,lon:5.4},gazole_prix:1.7});
const page=(results,complete=true,nextCursor=null,snapshot='s1',total)=>({schemaVersion:2,results,complete,nextCursor,snapshot,...(total===undefined?{}:{total})});
const origin={lat:43.3,lon:5.4};
test('legacy rejected',()=>assert.throws(()=>normalizeV2Page({results:[]},'Gazole')));
test('bad fuel rejected',()=>assert.throws(()=>normalizeV2Page(page([]),'NO')));
test('v2 complete accepted',()=>assert.equal(normalizeV2Page(page([station('1')]),'Gazole').stations.length,1));
test('missing price excluded',()=>assert.equal(normalizeV2Page(page([{id:'1',geom:{lat:43.3,lon:5.4}}]),'Gazole').stations.length,0));
test('no snapshot rejected',()=>assert.throws(()=>normalizeV2Page(page([],true,null,''),'Gazole')));
test('complete cursor rejected',()=>assert.throws(()=>normalizeV2Page(page([],true,'x'),'Gazole')));
test('incomplete no cursor rejected',()=>assert.throws(()=>normalizeV2Page(page([],false),'Gazole')));
test('negative total rejected',()=>assert.throws(()=>normalizeV2Page(page([],true,null,'s1',-1),'Gazole')));
test('duplicate page id rejected',()=>assert.throws(()=>normalizeV2Page(page([station('1'),station('1')]),'Gazole')));
test('wrong version rejected',()=>assert.throws(()=>normalizeV2Page({...page([]),schemaVersion:3},'Gazole')));
test('one complete page',async()=>{const r=await loadV2({fetchFn:async()=>({ok:true,json:async()=>page([station('1')],true,null,'s1',1)}),fuel:'Gazole',origin,radiusKm:5});assert.equal(r.complete,true);assert.equal(r.received,1)});
test('two pages with snapshot',async()=>{let n=0;const r=await loadV2({fetchFn:async()=>({ok:true,json:async()=>++n===1?page([station('1')],false,'next','s1',2):page([station('2')],true,null,'s1',2)}),fuel:'Gazole',origin,radiusKm:5});assert.equal(r.complete,true);assert.equal(r.received,2)});
test('snapshot changes => incomplete',async()=>{let n=0;const r=await loadV2({fetchFn:async()=>({ok:true,json:async()=>++n===1?page([station('1')],false,'next','s1',2):page([station('2')],true,null,'s2',2)}),fuel:'Gazole',origin,radiusKm:5});assert.equal(r.complete,false);assert.equal(r.reason,'snapshot_changed')});
test('total mismatch => incomplete',async()=>{const r=await loadV2({fetchFn:async()=>({ok:true,json:async()=>page([station('1')],true,null,'s1',2)}),fuel:'Gazole',origin,radiusKm:5});assert.equal(r.reason,'total_mismatch')});
test('server 500 => incomplete',async()=>{const r=await loadV2({fetchFn:async()=>({ok:false,status:500}),fuel:'Gazole',origin,radiusKm:5});assert.equal(r.complete,false)});
test('cursor is sent to proxy',async()=>{let n=0,secondUrl;await loadV2({fetchFn:async(url)=>{n++;if(n===2)secondUrl=new URL(url);return {ok:true,json:async()=>n===1?page([station('1')],false,'a','s1',2):page([station('2')],true,null,'s1',2)}},fuel:'Gazole',origin,radiusKm:5});assert.equal(secondUrl.searchParams.get('cursor'),'a');assert.equal(secondUrl.searchParams.get('snapshot'),'s1')});
test('limit validated',()=>assert.throws(()=>createV2PageFetcher({fetchFn:async()=>{},fuel:'Gazole',limit:501})));
test('fuel field selection',()=>assert.equal(normalizeV2Page(page([{id:'1',geom:{lat:43.3,lon:5.4},e10_prix:1.5}]),'E10').stations[0].price,1.5));
test('page loop => incomplete',async()=>{const r=await loadV2({fetchFn:async()=>({ok:true,json:async()=>page([],false,'repeat')}),fuel:'Gazole',origin,radiusKm:5});assert.equal(r.reason,'cursor_loop')});
test('cancelled signal',async()=>{const controller=new AbortController();controller.abort();const r=await loadV2({fetchFn:async()=>{throw Error('should not call')},fuel:'Gazole',origin,radiusKm:5,signal:controller.signal});assert.equal(r.status,'cancelled')});
